    -- Sync the concept_id sequence to avoid duplicate key errors on PostgreSQL
    PERFORM setval('concept_concept_id_seq', (SELECT MAX(concept_id) FROM concept));

    SELECT concept_source_id INTO v_concept_source_id FROM concept_reference_source WHERE name = 'HL7-MedicationAdministrationStatus';
    SELECT concept_map_type_id INTO v_concept_map_type_id FROM concept_map_type WHERE name = 'SAME-AS';

    -- Medication Administration Status (Parent)
    INSERT INTO concept (datatype_id, class_id, is_set, creator, date_created, changed_by, date_changed, uuid)
    SELECT (SELECT concept_datatype_id FROM concept_datatype WHERE name = 'Coded'), (SELECT concept_class_id FROM concept_class WHERE name = 'Misc'), false, 1, CURRENT_TIMESTAMP, 1, CURRENT_TIMESTAMP, gen_random_uuid()::varchar
    RETURNING concept_id INTO v_concept_id;

    INSERT INTO concept_name (concept_id, name, locale, locale_preferred, creator, date_created, concept_name_type, uuid)
    VALUES (v_concept_id, 'Medication Administration Status', 'en', false, 1, CURRENT_TIMESTAMP, 'SHORT', gen_random_uuid()::varchar);

    INSERT INTO concept_name (concept_id, name, locale, locale_preferred, creator, date_created, concept_name_type, uuid)
    VALUES (v_concept_id, 'Medication Administration Status', 'en', true, 1, CURRENT_TIMESTAMP, 'FULLY_SPECIFIED', gen_random_uuid()::varchar);

    INSERT INTO concept_description (concept_id, description, locale, creator, date_created, uuid)
    VALUES (v_concept_id, 'Medication Administration Status', 'en', 1, CURRENT_TIMESTAMP, gen_random_uuid()::varchar);

    v_parent_concept_id := v_concept_id;

