    VALUES (v_reference_term_id, v_concept_map_type_id, 1, CURRENT_TIMESTAMP, v_concept_id, gen_random_uuid()::varchar);

    INSERT INTO concept_answer (concept_id, answer_concept, date_created, creator, uuid, sort_weight)
    VALUES (v_parent_concept_id, v_concept_id, CURRENT_TIMESTAMP, 1, gen_random_uuid()::varchar, 1);

