    INSERT INTO concept_answer (concept_id, answer_concept, date_created, creator, uuid, sort_weight)
    VALUES (v_parent_concept_id, v_concept_id, CURRENT_TIMESTAMP, 1, gen_random_uuid()::varchar, 4);

    -- MA-Entered in Error
    INSERT INTO concept (datatype_id, class_id, is_set, creator, date_created, changed_by, date_changed, uuid)
    SELECT (SELECT concept_datatype_id FROM concept_datatype WHERE name = 'N/A'), (SELECT concept_class_id FROM concept_class WHERE name = 'Misc'), false, 1, CURRENT_TIMESTAMP, 1, CURRENT_TIMESTAMP, gen_random_uuid()::varchar
