    INSERT INTO fhir_concept_source (concept_source_id, url, name, creator, date_created, uuid)
    VALUES (v_concept_source_id, 'http://hl7.org/fhir/CodeSystem/medication-admin-status', 'HL7-MedicationAdministrationStatus', 1, CURRENT_TIMESTAMP, gen_random_uuid()::varchar);

